# -------------------------------------------------------------------------
# [핵심 수정] 한글 이름을 최우선으로 대표 이름(primary_names)으로 지정하는 로직
# -------------------------------------------------------------------------
primary_names = {}
for k, v in tmap.items():
    if v not in primary_names:
        primary_names[v] = k
    else:
        # 이미 등록된 대표 이름이 한글이 아닌데, 새로 확인하는 키(k)에 한글이 있다면 덮어쓰기!
        current_name = primary_names[v]
        if not re.search(r'[가-힣]', current_name) and re.search(r'[가-힣]', k):
            primary_names[v] = k
