                    # ⑤ 기회비용 (10년물 미국채 금리 대비 이익수익률 ERP)
                    if f_pe > 0 and (erp >= 0.5 or (roic_val >= 20.0 and erp >= -0.8)): c5_st = "pass"
                    elif f_pe > 0 and erp >= -1.5: c5_st = "warn"
                    else: c5_st = "fail"
                    c5_sub = f"이익수익률 {ey:.1f}% (국채 {erp:+.1f}%p)" if f_pe > 0 else "산출 불가(적자)"

