                    # - 공식 1 (버핏 10% 허들 역산): 1/현재PER + (요구 성장률) = 10%  ==> 요구 성장률 vs 실제 FCF 성장률 비교
                    # - 공식 2 (국채+5%p 허들 역산): 1/현재PER + (국채대비 요구 성장률) = 10년물 국채금리 + 5%
