                            b_sub = f"공식 [ 1/현재PER({cur_ey:.2f}%) + 요구성장률({req_g_10:+.2f}%) = 10.0% ] ➔ 연 10% 수익을 위해 매년 {req_g_10:+.1f}% 성장이 필요한데, 실제 FCF는 매년 {actual_fcf_g:+.1f}%씩 성장해 충분한 안전마진이 확인됩니다."
