with tab6:
    st.subheader(t("기업 경영진 및 거버넌스 순위 (AI 평가)", "Management & Governance Ranking"))
    st.caption(t("※ AGIE의 6원칙(정직성, 자본 배분, 주주환원, 도덕성 등)을 기준으로 심층 평가가 완료된 기업들의 순위입니다.", "※ Ranking based on integrity, capital allocation, and shareholder return."))
    
    @st.cache_data(ttl=3600)
    def get_gov_ranking_data(tmap_size):  # [수정] 등록된 기업 총개수를 센서로 받습니다.
        rank_data = []
        seen_codes = set()
        
        for name, tk in tmap.items():
            kr = tk.endswith('.KS') or tk.endswith('.KQ')
            cd = tk.split('.')[0] if kr else tk
            
            if cd in seen_codes: continue
            seen_codes.add(cd)
            
            text = fetch_governance_criticism(tk, cd, "CEO")
            
            # 평가가 안 된 기본 텍스트는 순위에서 제외
            if "위키 및 공공 기록 스크리닝 결과" in text: continue
                
            # --- [수정된 랭킹용 문맥 분석 엔진] ---
            kw_super_pos = ["교과서적", "자본 배분", "정직", "가장 신뢰받는", "파격적인 주주가치", "전량 소각", "압도적인 마진", "마진 극대화", "탁월한 자본수익률", "철저한 ROE", "연속 배당 성장", "버핏이 극찬", "멍거가 극찬", "리루가 극찬", "거장의 극찬", "버핏의 투자", "버핏이", "멍거가", "리루가", "극찬"]
            kw_high_pos = ["자사주 매입", "주주 환원", "주주친화", "상생", "압도적인", "독보적", "독점적", "시장 장악", "완결형", "적극적인 주주환원", "잉여현금 극대화", "배당 확대", "주당가치 제고", "자본 효율적", "주주환원율 로드맵"]
            kw_pos = ["검증된", "수익성 개선", "안정적", "선점", "실행력", "투명한", "신뢰도", "프리미엄", "우위", "현금 창출력", "흑자 달성", "1위", "장악력", "본업에 집중", "강력한"]
            
            kw_fatal = ["구속", "횡령", "배임", "분식회계", "사기", "은폐", "조작", "부품 바꿔치기", "거버넌스 붕괴", "파탄", "먹튀", "사망 참사", "부당대출", "비리", "미공개 정보", "내부통제 부실", "압수수색"]
            kw_high_neg = ["사법", "물적분할", "유상증자", "합병 비율", "주주가치 훼손", "주주가치 희석", "뇌물", "탈세", "유죄", "불법", "강제노동", "배당 중단", "무단", "독성", "파산", "정경유착", "비자금", "불투명한", "기밀 유출"]
            kw_neg = ["과징금", "집단소송", "배상금", "결함", "환경 파괴", "키맨 리스크", "노동 환경", "노무", "반독점", "독점 규제", "무리한", "출혈", "낙하산", "가동률 하락", "소송", "제재", "적자 방치", "부채 부담", "레버리지", "규제 마찰", "지배구조 불안", "오버행", "통제 리스크", "이탈", "보안 침해", "먹통", "개인정보 유출"]
            kw_minor_neg = ["사이클", "변동성", "침체", "둔화", "관세", "마진 희석", "경쟁 격화", "잠식", "포화", "지정학적", "정체", "우려"]
            
            past_modifiers = ["과거", "전임", "수십 년간", "이전", "2008년", "금융위기 당시"]

            raw_score = 0
            is_current_fatal = False

            sentences = [s.strip() for s in text.replace('\n', '. ').split('.') if s.strip()]
            for sentence in sentences:
                is_past_context = any(pm in sentence for pm in past_modifiers)
                
                for k in kw_fatal:
                    if k in sentence:
                        if is_past_context: raw_score -= 15
                        else: is_current_fatal = True
                        sentence = sentence.replace(k, "")
                for k in kw_high_neg:
                    if k in sentence:
                        raw_score -= 10 if is_past_context else 30
                        sentence = sentence.replace(k, "")
                for k in kw_neg:
                    if k in sentence:
                        raw_score -= 5 if is_past_context else 20
                        sentence = sentence.replace(k, "")
                for k in kw_minor_neg:
                    if k in sentence:
                        raw_score -= 5
                        sentence = sentence.replace(k, "")
                        
                for k in kw_super_pos:
                    if k in sentence: raw_score += 40; sentence = sentence.replace(k, "")
                for k in kw_high_pos:
                    if k in sentence: raw_score += 30; sentence = sentence.replace(k, "")
                for k in kw_pos:
                    if k in sentence: raw_score += 15; sentence = sentence.replace(k, "")

            if is_current_fatal:
                ceo_final = -40
            else:
                max_raw_score = 120.0
                ratio = max(-1.0, min(1.0, raw_score / max_raw_score))
                scaled_score = ratio * 40.0

                if scaled_score >= 38: ceo_final = 40
                elif scaled_score >= 34: ceo_final = 36
                elif scaled_score >= 30: ceo_final = 32
                elif scaled_score >= 26: ceo_final = 28
                elif scaled_score >= 22: ceo_final = 24
                elif scaled_score >= 18: ceo_final = 20
                elif scaled_score >= 14: ceo_final = 16
                elif scaled_score >= 10: ceo_final = 12
                elif scaled_score >= 6: ceo_final = 8
                elif scaled_score >= 2: ceo_final = 4
                elif scaled_score >= -2: ceo_final = 0
                elif scaled_score >= -6: ceo_final = -4
                elif scaled_score >= -10: ceo_final = -8
                elif scaled_score >= -14: ceo_final = -12
                elif scaled_score >= -18: ceo_final = -16
                elif scaled_score >= -22: ceo_final = -20
                elif scaled_score >= -26: ceo_final = -24
                elif scaled_score >= -30: ceo_final = -28
                elif scaled_score >= -34: ceo_final = -32
                elif scaled_score >= -38: ceo_final = -36
                else: ceo_final = -40
            
            if ceo_final >= 40: tier = "Tier 1 (최우수)"
            elif ceo_final >= 32: tier = "Tier 2 (우수)"
            elif ceo_final >= 16: tier = "Tier 3 (양호)"
            elif ceo_final >= 8: tier = "Tier 4 (보통)"
            elif ceo_final > -40: tier = "Tier 5 (유의)"
            else: tier = "Tier 6 (집중점검)"
            
            # F급은 치명적인 단점을 요약해서 보여줌
            if ceo_final == -40 and "단점:" in text:
                summary = "[리스크] " + text.split("단점:")[1].strip()
            elif "장점:" in text and "단점:" in text:
                summary = text.split("단점:")[0].replace("장점:", "").strip()
            else:
                summary = text[:60] + "..."
            
            rank_data.append({
                "티커": tk,
                "기업명": primary_names.get(tk, name),
                "점수": ceo_final,
                "등급": tier,
                "평가 요약": summary
            })
        
        rank_data.sort(key=lambda x: x["점수"], reverse=True)
        for i, item in enumerate(rank_data):
            item["순위"] = i + 1
        return rank_data
        
    with st.spinner("경영진 데이터를 계산 중입니다..."):
        gov_df = pd.DataFrame(get_gov_ranking_data(len(tmap)))
    
    # ▼▼ 교체할 탭 6 코드 ▼▼
    st.caption("👉 **표에서 원하는 기업의 행(줄)을 클릭하면 즉시 AI 분석이 실행됩니다!**")
    
    event_gov = st.dataframe(
        gov_df, 
        height=800, 
        use_container_width=True, 
        hide_index=True, 
        column_order=["순위", "등급", "티커", "기업명"], 
        column_config={
            "순위": st.column_config.NumberColumn(t("순위", "Rank"), width="small"),
            "등급": st.column_config.TextColumn(t("등급", "Tier"), width="small"),
            "티커": st.column_config.TextColumn(t("티커", "Ticker"), width="small"),
            "기업명": st.column_config.TextColumn(t("기업명", "Company"), width="large")
        },
        on_select="rerun",
        selection_mode="single-row"
    )
    
    if event_gov and len(event_gov.selection.rows) > 0:
        selected_idx = event_gov.selection.rows[0]
        matched_ticker_gov = gov_df.iloc[selected_idx]["티커"]
        
        if st.session_state.get("preview_tk_tab6") != matched_ticker_gov:
            select_ticker(matched_ticker_gov)
            with st.spinner(f"AI가 {matched_ticker_gov} 데이터를 스캔 중입니다..."):
                st.session_state["preview_tab6"] = generate_quick_ai_preview(matched_ticker_gov)
                st.session_state["preview_tk_tab6"] = matched_ticker_gov
    else:
        if "preview_tab6" in st.session_state:
            del st.session_state["preview_tab6"]
            del st.session_state["preview_tk_tab6"]
                
    if "preview_tab6" in st.session_state:
        st.markdown(st.session_state["preview_tab6"], unsafe_allow_html=True)
        if "preview_tk_tab6" in st.session_state:
            if st.button(t(f" [{st.session_state['preview_tk_tab6']}] 탭 1(메인 분석)에 완벽 고정하기 (클릭 후 탭 1로 이동)", f" Pin [{st.session_state['preview_tk_tab6']}] to Tab 1"), key="btn_fix_tab6", use_container_width=True, type="primary"):
                st.session_state.sync_tk = st.session_state["preview_tk_tab6"]
                st.rerun()
