                    (f"둘째 올해 연초대비 1등! {top_ytd['업종_한줄']} 업종 무려 {top_ytd['YTD']:+.1f}% 상승!", "SEC_3"),
                    (f"셋째 올해 가장 소외된 꼴찌! {bot_ytd['업종_한줄']} 업종 {bot_ytd['YTD']:+.1f}% 기록!", "SEC_4"),
                    ("그래서 결론! 지금 월가 돈이 쓸려가는 진짜 주도 업종은 바로", "SEC_1")
