                            _draw_hm_frame(idx_h, stxt).save(f_im)
                            tts_h = stxt.replace("S&P500", "에스앤피 오백").replace("%", "퍼센트").replace("4가지", "네가지")
                            loop = asyncio.new_event_loop()
