    # =========================================================================
    st.markdown("#### 4️⃣ 연초 대비(Since Dec 31) 섹터별 주가 변화율(가로축) vs 12개월 선행 EPS 변화율(세로축)")
    st.caption("👉 **왼쪽 위(2사분면: 주가는 하락했으나 EPS는 상승)**에 위치한 섹터일수록 **'실적 추정치는 오르는데 가격만 내려온 저평가 괴리 섹터(대표: 기술 IT +11.8% EPS / -6.5% 주가)'**에 해당합니다.")

